css:
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;700&family=Syne:wght@800&display=swap');

:root {
  --bg-main: #0a0a0a;
  --bg-card: #171717;
  --bg-header: #0a0a0a;
  --accent: #00ff9d;
  --text-main: #ffffff;
  --text-gray: #a3a3a3;
  --border-color: #333333;
  --font-main: 'Space Grotesk', sans-serif;
  --font-heading: 'Syne', sans-serif;
  --shadow-sm: 8px 8px 0px #00ff9d;
  --radius: 0px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body { 
  font-family: var(--font-main); 
  background-color: var(--bg-main); 
  color: var(--text-gray); 
  line-height: 1.5; 
  display: flex; 
  flex-direction: column; 
  min-height: 100vh; 
}

a { text-decoration: none; color: inherit; transition: 0.1s; }
a:hover { color: var(--accent); }

h1, h2, h3, h4 { 
  color: var(--text-main); 
  font-family: var(--font-heading); 
  letter-spacing: -1px;
  text-transform: uppercase;
}

.container { max-width: 1200px; margin: 0 auto; padding: 0 20px; width: 100%; }

.site-header { 
  background: var(--bg-header); 
  border-bottom: 4px solid var(--accent); 
  padding: 30px 0; 
}

.header-top { 
  display: flex; 
  justify-content: space-between; 
  align-items: center; 
  max-width: 1200px; 
  margin: 0 auto; 
  padding: 0 20px;
}

.logo { 
  font-size: 2.5rem; 
  color: var(--text-main); 
  font-family: var(--font-heading); 
  font-weight: 800; 
  text-transform: uppercase;
  border: 2px solid var(--text-main);
  padding: 5px 15px;
}

.nav-links { display: flex; gap: 30px; margin-top: 0; }
.nav-links a { font-weight: 700; text-transform: uppercase; letter-spacing: 1px; }

.bottom-grid { 
  display: grid; 
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); 
  gap: 40px; 
  margin: 60px 0; 
}

.post-thumb-card { 
  background: var(--bg-card); 
  padding: 30px; 
  border: 2px solid var(--text-main); 
  box-shadow: var(--shadow-sm);
  display: flex; 
  flex-direction: column; 
  transition: 0.2s; 
}

.post-thumb-card:hover { 
  background: var(--accent);
  color: #000;
  transform: translate(-4px, -4px);
}

.cat-badge { 
  background: var(--text-main); 
  color: var(--bg-main); 
  padding: 2px 8px; 
  font-size: 0.7rem; 
  font-weight: 900;
  text-transform: uppercase; 
  display: inline-block; 
  margin-bottom: 15px; 
}

.post-thumb-title { font-size: 1.5rem; font-family: var(--font-heading); }

.post-container { 
  max-width: 800px; 
  margin: 60px auto; 
  background: var(--bg-card); 
  padding: 60px; 
  border: 4px solid var(--text-main); 
}

.post-h1 { font-size: 3rem; margin-bottom: 30px; color: var(--accent); }

.post-meta-info { 
  display: flex; 
  align-items: center; 
  gap: 20px; 
  margin-bottom: 40px; 
  border-top: 2px solid var(--border-color); 
  padding-top: 20px; 
}

.post-meta-info img { width: 60px; height: 60px; border: 2px solid var(--accent); }

.post-content { font-size: 1.2rem; }
.post-content h2 { margin: 50px 0 25px; font-size: 2rem; color: var(--accent); }
.post-content a { color: var(--accent); border-bottom: 2px solid var(--accent); }

.pagination { display: flex; justify-content: center; gap: 15px; margin: 60px 0; }

.page-link { 
  width: 50px; 
  height: 50px; 
  display: flex; 
  align-items: center; 
  justify-content: center; 
  background: var(--bg-card); 
  border: 2px solid var(--text-main); 
  font-weight: 800; 
}

.page-link.active { background: var(--accent); color: #000; border-color: var(--accent); }

.site-footer { 
  background: #000; 
  padding: 60px 0; 
  border-top: 4px solid var(--accent); 
  text-align: center; 
  margin-top: auto; 
  font-weight: 700;
}
